#pragma once
// tev_eval — a PURE C++ evaluator of the GX TEV combiner that MIRRORS the GLSL
// generated by tev_shader.cpp (write_regular / write_stage), so the per-pixel CPU
// trace (/pixblend, /tevtrace) and the render_test unit and the shipping shader all
// share ONE source of truth for the per-stage integer math + the register mapping.
//
// Faithful to the GameCube/Wii TEV integer pipeline (Dolphin PixelShaderGen). The
// one detail that this header exists to PIN DOWN: the GX TEV colour registers are
//   [0]=TEVPREV/CPREV, [1]=TEVREG0(=C0), [2]=TEVREG1(=C1), [3]=TEVREG2(=C2)
// and the combiner inputs c0/c1/c2 read registers 1/2/3 while `prev` is initialised
// from register 0 (Dolphin: `int4 c0=COLORS[1], c1=COLORS[2], c2=COLORS[3],
// prev=COLORS[0]`). An off-by-one here turns NgxTevState::tev_color[0] (CPREV) into
// the combiner's c0 and drops the real C2 — the ti=64 plaza magenta bug (s0 reads
// c0 as input d, getting CPREV(-90,0,-114,a135) instead of C0(255,255,255,a255)).
//
// No Vulkan, no guest RAM, no Dolphin: texture sampling is supplied by a callback so
// the evaluator stays unit-testable. Texel values are raw RGBA 0..255 (the per-stage
// texture/raster swizzle from the swap tables is applied INSIDE this evaluator).

#include "../ngx/ngx_render_data.h"
#include <cstdint>

namespace tev_eval {

inline int clampi(int v, int lo, int hi) { return v < lo ? lo : (v > hi ? hi : v); }

// Decoded combiner register (matches tev_shader.cpp decode_cc/decode_ac bit layout).
struct Comb { int a, b, c, d, bias, op, clamp, scale, dest; };
inline Comb decode_cc(uint32_t e) {
    return { (int)(e >> 12) & 0xf, (int)(e >> 8) & 0xf, (int)(e >> 4) & 0xf, (int)e & 0xf,
             (int)(e >> 16) & 3, (int)(e >> 18) & 1, (int)(e >> 19) & 1,
             (int)(e >> 20) & 3, (int)(e >> 22) & 3 };
}
inline Comb decode_ac(uint32_t e) {
    return { (int)(e >> 13) & 7, (int)(e >> 10) & 7, (int)(e >> 7) & 7, (int)(e >> 4) & 7,
             (int)(e >> 16) & 3, (int)(e >> 18) & 1, (int)(e >> 19) & 1,
             (int)(e >> 20) & 3, (int)(e >> 22) & 3 };
}

// One regular-combiner component — byte-for-byte the GLSL write_regular() integer math:
// (d {bias}{<<scale}) op (lerp(a,b,c){<<scale}{round}) >>8 {>>scale}, then clamp.
inline int regular_comp(int a, int b, int c, int d, int bias, int op, int clamp, int scale) {
    static const int bias_v[4] = { 0, 128, -128, 0 };
    const int sl = (scale == 1) ? 1 : (scale == 2) ? 2 : 0;   // left shift for scale 0/1/2
    int dterm = (d + bias_v[bias]) << sl;
    long lerp = ((long)(a << 8) + (long)(b - a) * (c + (c >> 7))) << sl;
    if (scale != 3) lerp += op ? 127 : 128;                   // op add/sub rounding
    lerp >>= 8;
    int res = op ? (int)(dterm - (long)lerp) : (int)(dterm + (long)lerp);
    if (scale == 3) res >>= 1;                                // Divide2
    return clamp ? clampi(res, 0, 255) : clampi(res, -1024, 1023);
}

// Konst RGB (GXTevKColorSel) into out[0..2]; faithful to tev_shader.cpp KSEL_C.
inline void konst_rgb(const NgxTevState& S, int ksel, int out[3]) {
    static const int cc8[8] = { 255, 223, 191, 159, 128, 96, 64, 32 };
    const int ks = ksel & 31;
    if (ks < 8) { out[0] = out[1] = out[2] = cc8[ks]; }
    else if (ks < 12) { out[0] = out[1] = out[2] = 0; }
    else if (ks < 16) { for (int k = 0; k < 3; k++) out[k] = S.kcolor[ks - 12][k]; }
    else { const int comp = (ks - 16) / 4, reg = (ks - 16) & 3; for (int k = 0; k < 3; k++) out[k] = S.kcolor[reg][comp]; }
}
// Konst alpha (GXTevKAlphaSel); faithful to KSEL_A.
inline int konst_a(const NgxTevState& S, int kasel) {
    static const int cc8[8] = { 255, 223, 191, 159, 128, 96, 64, 32 };
    const int ka = kasel & 31;
    if (ka < 8) return cc8[ka];
    if (ka < 16) return 0;
    const int comp = (ka - 16) / 4, reg = (ka - 16) & 3;
    return S.kcolor[reg][comp];
}

// Per-stage intermediate state captured for the trace (all RGBA, integer GX units).
struct StageTrace {
    int textemp[4], rastemp[4], konst[4];      // stage inputs (after swizzle)
    int prev[4], c0[4], c1[4], c2[4];          // register file AFTER this stage
};

// Supplies the raw RGBA 0..255 texel for the given stage's bound texmap (already
// sampled at the stage's texcoord UV). Return false → textemp defaults to white.
struct TexelSource {
    virtual bool sample(int stage, int texmap, int texcoord, int out_rgba[4]) const = 0;
    virtual ~TexelSource() = default;
};

// Evaluate the whole material's combiner for one fragment. col0/col1 = the two raster
// colour channels (0..255 RGBA). Writes the final RGBA into out_rgba[4]; if trace !=
// nullptr it must point at StageTrace[16] and receives per-stage state.
inline void eval(const NgxTevState& S, const int col0[4], const int col1[4],
                 const TexelSource& tex, int out_rgba[4], StageTrace* trace) {
    // Register file: prev initialised from CPREV (tev_color[0]); c0/c1/c2 = tev_color[1..3].
    int prev[4]; for (int k = 0; k < 4; k++) prev[k] = S.tev_color[0][k];
    int reg[3][4];   // reg[0]=C0, reg[1]=C1, reg[2]=C2
    for (int c = 0; c < 3; c++) for (int k = 0; k < 4; k++) reg[c][k] = S.tev_color[c + 1][k];

    int ns = S.num_stages; if (ns < 1) ns = 1; if (ns > 16) ns = 16;
    for (int sgi = 0; sgi < ns; sgi++) {
        const NgxTevStage& sg = S.stage[sgi];
        const Comb cc = decode_cc(sg.color_env);
        const Comb ac = decode_ac(sg.alpha_env);

        // Raster colour (channel + swap table). color_chan: COLOR0/COLOR0A0 → col0,
        // COLOR1/COLOR1A1 → col1, else zero.
        int rasraw[4] = { 0, 0, 0, 0 };
        if (sg.color_chan == 0 || sg.color_chan == 4) { for (int k = 0; k < 4; k++) rasraw[k] = col0[k]; }
        else if (sg.color_chan == 1 || sg.color_chan == 5) { for (int k = 0; k < 4; k++) rasraw[k] = col1[k]; }
        const uint8_t rsw = S.swap_table[sg.alpha_env & 3];
        const uint8_t tsw = S.swap_table[(sg.alpha_env >> 2) & 3];
        int rastemp[4] = { rasraw[(rsw >> 6) & 3], rasraw[(rsw >> 4) & 3], rasraw[(rsw >> 2) & 3], rasraw[rsw & 3] };

        // Texture sample (this stage's texmap/texcoord) + swap table.
        int traw[4] = { 255, 255, 255, 255 };
        const int tc = sg.texcoord < 8 ? sg.texcoord : 0;
        const int tm = sg.texmap < 8 ? sg.texmap : 0;
        tex.sample(sgi, tm, tc, traw);
        int textemp[4] = { traw[(tsw >> 6) & 3], traw[(tsw >> 4) & 3], traw[(tsw >> 2) & 3], traw[tsw & 3] };

        // Konst.
        int konst[4]; konst_rgb(S, sg.kcsel, konst); konst[3] = konst_a(S, sg.kasel);

        // Combiner input selectors (faithful to CC_IN / CA_IN).
        auto cin = [&](int idx, int ch) -> int { switch (idx) {
            case 0: return prev[ch]; case 1: return prev[3]; case 2: return reg[0][ch]; case 3: return reg[0][3];
            case 4: return reg[1][ch]; case 5: return reg[1][3]; case 6: return reg[2][ch]; case 7: return reg[2][3];
            case 8: return textemp[ch]; case 9: return textemp[3]; case 10: return rastemp[ch]; case 11: return rastemp[3];
            case 12: return 255; case 13: return 128; case 14: return konst[ch]; default: return 0; } };
        auto ain = [&](int idx) -> int { switch (idx) {
            case 0: return prev[3]; case 1: return reg[0][3]; case 2: return reg[1][3]; case 3: return reg[2][3];
            case 4: return textemp[3]; case 5: return rastemp[3]; case 6: return konst[3]; default: return 0; } };

        // Colour combine.
        int dst_c[3];
        if (cc.bias != 3) for (int ch = 0; ch < 3; ch++) {
            int a = cin(cc.a, ch) & 255, b = cin(cc.b, ch) & 255, c = cin(cc.c, ch) & 255, d = cin(cc.d, ch);
            dst_c[ch] = regular_comp(a, b, c, d, cc.bias, cc.op, cc.clamp, cc.scale);
        } else for (int ch = 0; ch < 3; ch++) dst_c[ch] = cin(cc.d, ch);  // compare modes: coarse approximation
        // Alpha combine.
        int dst_a;
        if (ac.bias != 3) { int a = ain(ac.a) & 255, b = ain(ac.b) & 255, c = ain(ac.c) & 255, d = ain(ac.d);
            dst_a = regular_comp(a, b, c, d, ac.bias, ac.op, ac.clamp, ac.scale);
        } else dst_a = ain(ac.d);

        int* cd = cc.dest == 0 ? prev : reg[cc.dest - 1];
        cd[0] = dst_c[0]; cd[1] = dst_c[1]; cd[2] = dst_c[2];
        int* ad = ac.dest == 0 ? prev : reg[ac.dest - 1];
        ad[3] = dst_a;

        if (trace) { StageTrace& t = trace[sgi];
            for (int k = 0; k < 4; k++) { t.textemp[k] = textemp[k]; t.rastemp[k] = rastemp[k]; t.konst[k] = konst[k];
                t.prev[k] = prev[k]; t.c0[k] = reg[0][k]; t.c1[k] = reg[1][k]; t.c2[k] = reg[2][k]; }
        }
    }
    for (int k = 0; k < 4; k++) out_rgba[k] = prev[k];
}

}  // namespace tev_eval
